let scanFeed=[],afterPhoto=null,verificationResult=null,pollTimer=null;
function photo(url,cls='image-preview'){return url?`<img class="${cls}" src="${esc(url)}" alt="Incident evidence">`:'<div class="photo-placeholder">Sample record · no evidence photo</div>'}
function demoNote(){return state.live?'':`<div class="notice"><b>Demo Mode.</b> Select a simulated finding to rehearse the workflow. Photos are displayed but are not analyzed by AI. Sample confidence values are illustrative. Records reset when this page reloads.</div>`}
function secondary(){switch(state.page){case 'citizen':return citizen();case 'report':return reportPage();case 'incidents':return header('All incidents','One place to follow every issue, from report to repair.')+incidentTable();case 'map':return header('Incident map','See where civic issues need attention.')+mapPanel();case 'nearby':return header('Nearby issues','Explore incidents around your area.',`<button class="btn" id="nearby-location">${icon('pin')}Use my location</button>`)+mapPanel()+incidentTable(false);case 'reports':return header('My reports','Follow the progress of issues you reported.')+incidentTable(false,incidents.filter(i=>state.live?i.mine:i.mine));case 'resolved':return header('Resolved issues','A record of completed repairs and their visual review.')+incidentTable(false,incidents.filter(i=>i.status==='Resolved'));case 'detail':return incidentDetail();case 'tasks':case 'completed':return tasks();case 'workers':return workers();case 'analytics':return analytics();case 'drivescan':return driveScan();case 'assistant':return assistant();case 'settings':return settings();default:return header('Workspace not found','Choose a page from the navigation.')}}
function citizen(){const mine=incidents.filter(i=>state.live?i.mine:i.mine);return header('Your city. Your eyes.','Spot an issue. Share a photo. Follow the fix.',`<button class="btn primary" id="new-report">${icon('plus')}Report an issue</button>`)+`<div class="report-grid"><section class="panel"><div class="panel-body"><div class="eyebrow">Make your neighborhood better</div><h2>See something that needs attention?</h2><p>Capture a pothole, garbage accumulation, or standing water. CivicEye helps route the report to the right department.</p><div class="actions" style="margin-top:22px"><button class="btn primary" id="citizen-camera">${icon('camera')}Take a photo</button><button class="btn" data-page="report">${icon('upload')}Upload image</button></div></div></section><section class="panel"><div class="panel-body"><h3>My reporting activity</h3><div class="details-list"><div><label>Reports submitted</label><b>${mine.length}</b></div><div><label>Issues resolved</label><b>${mine.filter(i=>i.status==='Resolved').length}</b></div></div><p class="subtext">Your reports help determine the priority of an issue.</p></div></section></div><div style="margin-top:24px">${incidentTable(false,mine)}</div>`}
function reportPage(){const r=state.report||{};return header('Report a civic issue','A clear photo is the first step toward a clear resolution.')+`<div class="progress-steps"><span class="active">1 · Capture</span><span class="${r.analysis?'active':''}">2 · Review detection</span><span>3 · Submit & track</span></div>${demoNote()}<div class="report-grid"><section class="panel"><div class="panel-head"><h2>Visual evidence</h2><span class="subtext">Camera or image upload</span></div><div class="panel-body">${r.image?photo(r.image):`<div class="upload-zone">${icon('camera')}<h3>Capture what you can see</h3><p>Use a clear image of the issue.<br>Miniature road models work in Live AI Mode.</p><div class="actions"><button class="btn primary" id="open-camera">${icon('camera')}Open camera</button><button class="btn" id="upload-button">${icon('upload')}Upload image</button></div></div>`}<video id="camera" playsinline autoplay muted style="display:none"></video><div class="camera-controls actions" id="camera-controls" style="display:none"><button class="btn primary" id="capture">${icon('camera')}Capture photo</button><button class="btn" id="stop-camera">Close camera</button></div><input type="file" id="image-file" accept="image/jpeg,image/png,image/webp" class="screen-reader" aria-label="Upload incident image">${r.image?'<button class="button-link" id="replace-photo" style="margin-top:14px">Replace photo</button>':''}<label class="field">Area or address<input id="address" placeholder="e.g. Hospital Road, Indiranagar" value="${esc(r.address||'')}"></label><div class="actions"><button class="btn" id="locate">${icon('pin')}Use current location</button><span class="subtext">Or tap the map to set a location</span></div><div class="map" id="location-map" style="height:200px;margin-top:15px"></div><div class="details-list"><label class="field">Latitude<input id="lat" type="number" step="any" min="-90" max="90" value="${r.latitude??12.9735}"></label><label class="field">Longitude<input id="lng" type="number" step="any" min="-180" max="180" value="${r.longitude??77.642}"></label></div><label class="field">Location importance<select id="importance">${['residential','main road','school','hospital','market'].map(t=>`<option ${r.importance===t?'selected':''}>${t}</option>`).join('')}</select></label></div></section><section class="panel"><div class="panel-head"><h2>Detection & routing</h2>${icon('eye')}</div><div class="panel-body">${!state.live?`<label class="field">Simulated visual finding<select id="demo-type"><option value="Pothole">Pothole</option><option value="Waterlogging">Waterlogging / water-filled pothole</option><option value="Garbage">Garbage accumulation</option><option value="None">No civic issue detected</option></select></label><label class="field">Simulated severity<select id="demo-severity"><option>LOW</option><option selected>MEDIUM</option><option>HIGH</option></select></label>`:''}<button class="btn navy full" id="analyze" ${r.image?'':'disabled'}>${icon('spark')}${state.live||visionReady()?'Analyze image':'AI service required'}</button><div id="analysis-result" style="margin-top:22px">${r.analysis?analysisCard(r):'<div class="empty">Capture or upload an image to begin.</div>'}</div></div></section></div>`}
function analysisCard(r){const a=r.analysis;if(a.issue_type==='None')return `<div class="result"><h3>No civic issue detected</h3><p>${esc(a.explanation)}</p><p class="subtext">${state.live||a.demo===false?'This visual assessment may miss issues.':'Simulated result · no image analysis performed.'}</p></div>`;const p=priority({...r,...a,reports:1,created_at:now()});return `<div class="result"><div class="eyebrow">${a.demo===false?'Visual analysis':state.live?'Visual analysis':'Simulated finding'}</div><h3>${a.issue_type==='Waterlogging'?'Standing water detected':a.issue_type+' detected'}</h3><p>${esc(a.explanation)}</p><div class="details-list"><div><label>${a.demo===false||state.live?'Model assessment':'Illustrative confidence'}</label><b>${esc(confidenceText(a))}</b></div><div><label>Severity</label><b>${a.severity}</b></div><div><label>Suggested department</label><b>${departments[a.issue_type]} Department</b></div><div><label>Possible priority</label>${badge(p.level)}</div></div></div><div class="priority-explanation"><b>Why this priority?</b><ul>${p.reasons.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>${a.requires_review||a.confidence===null||a.confidence<.7?'<div class="notice" style="margin-top:15px">Low confidence. This report will require authority review.</div>':''}<p class="subtext">Status: Awaiting submission</p><button class="btn primary full" id="submit-incident" style="margin-top:15px">${icon('check')}Submit incident</button>`}
function incidentDetail(){const i=incidents.find(x=>x.id===state.selected?.id);if(!i)return header('Incident unavailable','This record is no longer available.');state.selected=i;const p=priority(i);return header(`${i.id} · ${i.issue_type}`,i.address,`<button class="btn" data-page="${state.role==='authority'?'incidents':state.role==='worker'?'tasks':'reports'}">Back to incidents</button>${badge(p.level)}`)+`<div class="two-col"><div><section class="panel"><div class="panel-head"><h2>Incident evidence</h2><span class="badge status">${esc(i.status)}</span></div><div class="panel-body">${photo(i.image_url)}<div class="details-list"><div><label>AI finding ${i.demo===false||state.live?'':'· demo sample'}</label><b>${i.issue_type}</b></div><div><label>${i.demo===false||state.live?'Model assessment':'Illustrative confidence'}</label><b>${esc(confidenceText(i))}</b></div><div><label>Severity</label><b>${i.severity}</b></div><div><label>Citizen reports</label><b>${i.reports}</b></div><div><label>Department</label><b>${esc(i.department)}</b></div><div><label>Reported</label><b>${new Date(i.created_at).toLocaleString('en-IN')}</b></div></div><div class="priority-explanation"><b>${p.level} priority · ${p.score}/100</b><ul>${p.reasons.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div></div></section><section class="panel" style="margin-top:24px"><div class="panel-head"><h2>Location</h2><span class="subtext">${i.latitude.toFixed(5)}, ${i.longitude.toFixed(5)}</span></div><div class="map" id="detail-map" style="height:220px"></div></section>${i.after_image_url?`<section class="panel" style="margin-top:24px"><div class="panel-head"><h2>Completion evidence</h2>${badge(i.status==='Resolved'?'RESOLVED':'MEDIUM')}</div><div class="panel-body"><div class="photo-pair"><div><h4>BEFORE</h4>${photo(i.image_url)}</div><div><h4>AFTER</h4>${photo(i.after_image_url)}</div></div><p>${esc(i.verification_explanation||'Review submitted repair evidence.')}</p></div></section>`:''}</div><div><section class="panel"><div class="panel-head"><h2>${state.role==='authority'?'Manage incident':state.role==='worker'?'Task actions':'Track progress'}</h2></div><div class="panel-body">${state.role==='authority'?`<label class="field">Assign a field worker<select id="worker-select"><option value="">Select worker</option>${(state.workers||[{id:'demo-worker',name:'Road Team A'},{id:'demo-waste',name:'Waste Team B'},{id:'demo-drainage',name:'Drainage Team C'}]).map(w=>`<option value="${esc(w.id)}">${esc(w.name)}</option>`).join('')}</select></label><button class="btn primary full" id="assign-worker" ${['Resolved','Rejected'].includes(i.status)?'disabled':''}>${icon('users')}Assign worker</button><label class="field">Responsible department<select id="department-select">${Object.values(departments).map(d=>`<option ${i.department===d?'selected':''}>${d}</option>`).join('')}</select></label><button class="btn full" id="change-department">Change department</button><div class="actions" style="margin-top:20px"><button class="btn" id="review-incident">Mark for review</button><button class="btn danger" id="reject-incident">Reject detection</button></div>${i.after_image_url&&i.status==='Review Required'?'<button class="btn primary full" id="authority-resolve" style="margin-top:15px">Approve repair after visual review</button>':''}`:state.role==='worker'?workerActions(i):`<p>Each status update appears here as your report progresses.</p>${i.mine?'':`<button class="btn primary full" id="support-incident">Confirm same issue</button>`}`}</div></section><section class="panel" style="margin-top:24px"><div class="panel-head"><h2>Status history</h2>${icon('clock')}</div><div class="panel-body"><div class="history">${(i.history||[{status:i.status,created_at:i.updated_at}]).map(h=>`<div><b>${esc(h.status)}</b><small>${new Date(h.created_at).toLocaleString('en-IN')}</small></div>`).join('')}</div></div></section></div></div>`}
function workerActions(i){if(['Resolved','Rejected'].includes(i.status))return '<div class="result"><h3>Task closed</h3><p>View the completion evidence and status history.</p></div>';const next={Assigned:['Accepted','Accept task'],Accepted:['En Route','En route'],'En Route':['On Site','On site'],'On Site':['In Progress','Start repair']}[i.status];if(next)return `<p>Current status: <b>${esc(i.status)}</b></p><button class="btn primary full" id="worker-next" data-status="${next[0]}">${icon('check')}${next[1]}</button>`;if(i.status==='In Progress'||i.status==='Review Required')return `<p>Repair complete? Upload a new after-repair image for visual verification.</p><button class="btn primary full" id="completion">${icon('upload')}Upload completion</button>`;return '<p>Awaiting assignment by the authority.</p>'}
function tasks(){const completed=state.page==='completed';const list=incidents.filter(i=>i.worker_id===(state.live?state.user?.id:'demo-worker')&&(completed?i.status==='Resolved':!['Resolved','Rejected'].includes(i.status)));return header(completed?'Completed tasks':'Your field assignments',completed?'Completed repairs and verification records.':'Accept the task, document the repair, and close the loop.')+`<div class="stats" style="grid-template-columns:repeat(3,1fr)">${[[list.length,completed?'Completed tasks':'Assigned tasks'],[list.filter(i=>['HIGH','CRITICAL'].includes(priority(i).level)).length,'High priority'],[incidents.filter(i=>i.worker_id===(state.live?state.user?.id:'demo-worker')&&i.status==='Resolved').length,'Total completed']].map(([n,l])=>`<div class="stat"><div class="stat-top">${l}</div><div class="stat-value">${n}</div></div>`).join('')}</div><div class="task-grid">${list.map(i=>`<section class="panel task-card"><div class="row-title"><span class="subtext">${esc(i.id)}</span>${badge(priority(i).level)}</div><h3>${i.issue_type}</h3><p>${icon('pin')}${esc(i.address)}</p><div class="task-photo">${i.image_url?`<img src="${esc(i.image_url)}" alt="Before repair">`:'Sample record · no before photo'}</div><div class="details-list"><div><label>Status</label><b>${esc(i.status)}</b></div><div><label>Distance</label><b>${state.position?distance(state.position,i).toFixed(0)+' m':'GPS unavailable'}</b></div></div><p class="subtext">Assigned ${ago(i.assigned_at||i.updated_at)}</p><button class="btn primary" data-incident="${esc(i.id)}">Open task</button></section>`).join('')||'<div class="panel empty">No tasks in this view. Assign a task from the authority dashboard to begin.</div>'}</div>`}
function workers(){const list=state.workers||[{id:'demo-worker',name:'Road Team A'},{id:'demo-waste',name:'Waste Team B'},{id:'demo-drainage',name:'Drainage Team C'}];return header('Field teams','See current assignments and team workloads.')+`<div class="task-grid">${list.map(w=>{const tasks=incidents.filter(i=>i.worker_id===w.id);return `<section class="panel task-card"><div class="issue-icon">${icon('users')}</div><h3>${esc(w.name)}</h3><p>${tasks.filter(i=>i.status!=='Resolved').length} open tasks · ${tasks.filter(i=>i.status==='Resolved').length} completed</p>${tasks.map(i=>`<button class="btn" data-incident="${esc(i.id)}">${esc(i.id)} · ${i.issue_type}</button>`).join('')}</section>`}).join('')}</div>`}
function analytics(){let r=incidents.filter(i=>i.status==='Resolved').length,pct=Math.round(r/Math.max(1,incidents.length)*100);return header('City intelligence','Understand the patterns behind your incident data.')+stats()+`<div class="analytics-grid">${chartPanel('Issues by type','issue_type')}${chartPanel('Issues by priority','priority')}${chartPanel('Most affected areas','address')}${chartPanel('Department workload','department',true)}<section class="panel"><div class="panel-head"><h2>Resolution rate</h2></div><div class="chart actions"><div class="donut" style="--pct:${pct}%"><div class="donut-inner">${pct}%</div></div><div><h3>${r} incidents resolved</h3><p>Out of ${incidents.length} reported incidents.</p><p class="subtext">Rejected detections are excluded from repairs.</p></div></div></section><section class="panel"><div class="panel-head"><h2>Recurring problem areas</h2></div><div class="chart">${recurring()}</div></section></div>`}
function recurring(){const groups={};incidents.forEach(i=>{const key=i.address+' · '+i.issue_type;groups[key]=(groups[key]||0)+1});const list=Object.entries(groups).filter(x=>x[1]>1);return list.length?list.map(([k,n])=>`<p><b>${esc(k)}</b> · ${n} separate incidents</p>`).join(''):'<p>No repeat incidents recorded in the current dataset.</p><p class="subtext">Repeated reports on one incident increase its priority; they are not counted as separate recurring issues.</p>'}
function driveScan(){return header('DriveScan','Capture road frames and review visible issues before submitting.')+demoNote()+`<div class="report-grid"><section class="panel"><div class="panel-head"><h2>Road camera</h2><span class="badge status" id="scan-status">Not scanning</span></div><div class="panel-body"><video id="camera" autoplay playsinline muted controls></video><div class="actions" style="margin-top:18px"><button class="btn primary" id="scan-start">${icon('camera')}Start camera scan</button><button class="btn" id="scan-stop">Stop</button><button class="btn" id="video-upload">Upload video</button><input type="file" id="video-file" accept="video/*" class="screen-reader" aria-label="Upload video"></div>${!state.live?'<label class="field">Simulated frame finding<select id="scan-demo-type"><option>Pothole</option><option>Garbage</option><option>Waterlogging</option><option value="None">No issue</option></select></label>':''}<button class="btn full" id="scan-frame" style="margin-top:16px">${icon('eye')}Analyze current frame</button><p class="subtext">Live Mode samples every 12 seconds. Review each finding before creating an incident. Use only while operated by a passenger or a safely parked vehicle.</p></div></section><section class="panel"><div class="panel-head"><h2>Detection feed</h2><span class="subtext">${scanFeed.length} frames</span></div><div id="scan-feed">${scanFeedHtml()}</div></section></div>`}
function scanFeedHtml(){return scanFeed.map((f,n)=>`<div class="queue-row"><div class="issue-icon">${icon('camera')}</div><div class="row-body"><div class="row-title">${f.analysis.issue_type==='None'?'No civic issue':f.analysis.issue_type} <span class="subtext">${new Date(f.time).toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})}</span></div><p>${esc(f.analysis.explanation)}</p>${f.analysis.issue_type==='None'?'':`<button class="button-link" data-frame="${n}">Review as incident</button>`}</div></div>`).join('')||'<div class="empty">Your analyzed frames will appear here.</div>'}
function assistant(){return header('Ask CivicEye','Answers grounded in the incidents in your current workspace.')+`<section class="panel"><div class="panel-body"><div class="issue-icon">${icon('spark')}</div><h2 style="margin-top:20px">What would you like to understand?</h2><p>This data assistant summarizes current records using deterministic queries. It does not use a generic language model.</p><div class="actions" style="margin:22px 0">${['Most common issues this week','Area with most unresolved incidents','Critical waterlogging incidents','Department with largest pending workload'].map(q=>`<button class="btn" data-question="${q}">${q}</button>`).join('')}</div><form id="ask-form" class="actions"><input id="question" placeholder="Ask about issues, areas, priority, or departments…" aria-label="Ask a question" required style="flex:1"><button class="btn primary">Ask CivicEye</button></form><div id="answer" aria-live="polite"></div></div></section>`}
function answer(q){let list=incidents.filter(i=>!['Resolved','Rejected'].includes(i.status)),text;if(/critical|waterlogging/i.test(q)){const found=list.filter(i=>i.issue_type==='Waterlogging'&&priority(i).level==='CRITICAL');text=found.length?found.map(i=>`${i.id}: ${i.address} — ${i.reports} reports, ${i.status}.`).join('\n'):'There are no unresolved critical waterlogging incidents in the current dataset.'}else if(/department|workload/i.test(q)){text=topGroup(list.filter(i=>['Pending','Review Required'].includes(i.status)),'department','Pending department workload')}else if(/area|unresolved/i.test(q)){text=topGroup(list,'address','Unresolved incidents by area')}else if(/common|week|type/i.test(q)){text=topGroup(incidents.filter(i=>Date.now()-new Date(i.created_at)<7*24*36e5),'issue_type','Issue types reported in the last 7 days')}else{text='Ask about common issue types, unresolved areas, critical waterlogging, or pending department workloads.'}$('#answer').innerHTML=`<div class="chat-answer">${esc(text).replace(/\n/g,'<br>')}<p class="subtext">Based on ${incidents.length} accessible records · ${state.live?'Live dataset':'Demo dataset'}</p></div>`}
function topGroup(list,key,label){const g={};list.forEach(i=>g[i[key]]=(g[i[key]]||0)+1);return label+':\n'+(Object.entries(g).sort((a,b)=>b[1]-a[1]).map(([k,n])=>`${k}: ${n} incident${n===1?'':'s'}`).join('\n')||'No matching incidents.');}
function settings(){return header('Connect live services','Switch from simulated results to authenticated, shared incident data.')+`<section class="panel" style="max-width:760px"><div class="panel-head"><h2>Supabase project</h2><span class="badge demo">${state.live?'Configured':'Not connected'}</span></div><div class="panel-body"><p>Supabase stores shared incident records. Image inference runs only on the local CivicEye ONNX service; cloud image inference is disabled.</p><form id="settings-form"><label class="field">Supabase project URL<input type="url" name="url" placeholder="https://your-project.supabase.co" value="${esc(state.config.supabaseUrl||'')}" required></label><label class="field">Public publishable / anon key<input name="key" placeholder="Public key only — never a service-role key" value="${esc(state.config.supabaseAnonKey||'')}" required></label><div class="actions"><button class="btn primary">Save & switch to Live Mode</button><button class="btn" type="button" id="disconnect">Use Demo Mode</button></div></form><div class="notice" style="margin-top:22px">Live Mode requires the supplied database security policies and Edge Function. Roles come from administrator-managed profiles. This connection form cannot grant administrative access.</div><p class="subtext">These public settings are remembered on this device. Incident records and photos in Live Mode are stored in Supabase.</p></div></section>`}
function rememberReport(){const r=state.report||(state.report={});for(const [id,key]of[['address','address'],['importance','importance'],['lat','latitude'],['lng','longitude']])if($('#'+id))r[key]=['lat','lng'].includes(id)?Number($('#'+id).value):$('#'+id).value;return r}
function validLocation(r){if(!Number.isFinite(r.latitude)||!Number.isFinite(r.longitude)||Math.abs(r.latitude)>90||Math.abs(r.longitude)>180||!r.address?.trim())throw Error('Add an address and valid latitude / longitude before submitting.');}
async function readImage(file){if(!file||!/^image\/(jpeg|png|webp)$/.test(file.type))throw Error('Choose a JPEG, PNG, or WebP image.');if(file.size>10*1024*1024)throw Error('Choose an image smaller than 10 MB.');const src=await new Promise((resolve,reject)=>{const f=new FileReader();f.onload=()=>resolve(f.result);f.onerror=reject;f.readAsDataURL(file)});return resizeImage(src)}
function resizeImage(src){return new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>{const scale=Math.min(1,1600/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=img.width*scale;c.height=img.height*scale;c.getContext('2d').drawImage(img,0,0,c.width,c.height);resolve(c.toDataURL('image/jpeg',.85))};img.onerror=()=>reject(Error('This image could not be read.'));img.src=src})}
async function camera(){if(!navigator.mediaDevices?.getUserMedia)throw Error('Camera unavailable. Use an image upload instead.');stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});const video=$('#camera');video.srcObject=stream;video.style.display='block';await video.play();if($('#camera-controls'))$('#camera-controls').style.display='flex';}
function captureFrame(){const v=$('#camera');if(!v?.videoWidth)throw Error('Wait for the camera or video to show a frame.');const c=document.createElement('canvas'),scale=Math.min(1,1600/v.videoWidth);c.width=v.videoWidth*scale;c.height=v.videoHeight*scale;c.getContext('2d').drawImage(v,0,0,c.width,c.height);return c.toDataURL('image/jpeg',.85)}
function closeCamera(){stream?.getTracks().forEach(t=>t.stop());stream=null;if($('#camera-controls'))$('#camera-controls').style.display='none';if($('#camera')){$('#camera').style.display='none';$('#camera').srcObject=null}}
async function analyze(){throw Error('Cloud image inference is disabled. Use the local CivicEye ONNX vision service.')}
function distance(a,b){const rad=v=>v*Math.PI/180,dlat=rad(b.latitude-a.latitude),dlng=rad(b.longitude-a.longitude),x=Math.sin(dlat/2)**2+Math.cos(rad(a.latitude))*Math.cos(rad(b.latitude))*Math.sin(dlng/2)**2;return 6371000*2*Math.atan2(Math.sqrt(x),Math.sqrt(1-x));}
function modal(html){$('#modal').innerHTML=html;$('#modal').showModal();$('#modal').querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('#modal').close());}
async function uploadEvidence(image){if(!state.live)return image;const blob=await(await fetch(image)).blob(),path=`${state.user.id}/${crypto.randomUUID()}.jpg`;const {error}=await client.storage.from('incident-images').upload(path,blob,{contentType:'image/jpeg',upsert:false});if(error)throw Error('Could not upload evidence: '+error.message);return client.storage.from('incident-images').getPublicUrl(path).data.publicUrl;}
async function submitReport(separate=false,duplicate=null){const r=rememberReport();validLocation(r);if(!r.analysis||r.analysis.issue_type==='None')throw Error('Analyze a visible issue first.');if(!separate&&!duplicate){const found=incidents.find(i=>i.issue_type===r.analysis.issue_type&&!['Resolved','Rejected'].includes(i.status)&&Date.now()-new Date(i.created_at)<7*24*36e5&&distance(i,r)<40);if(found){if($('#submit-incident'))$('#submit-incident').disabled=false;modal(`<h2>Possible existing incident found</h2><p>${esc(found.id)} · ${esc(found.address)}</p><div class="details-list"><div><label>Distance</label><b>${Math.round(distance(found,r))} m</b></div><div><label>Citizen reports</label><b>${found.reports}</b></div></div><div class="actions"><button class="btn" data-close>Cancel</button><button class="btn" id="separate">Create separate incident</button><button class="btn primary" id="same">Confirm same issue</button></div>`);$('#separate').onclick=()=>safe(async()=>{$('#modal').close();await submitReport(true)});$('#same').onclick=()=>safe(async()=>{$('#modal').close();await submitReport(false,found)});return}}
let id;if(state.live){if(!r.analysis.analysis_id){r.analysis=await analyze(r.image);if(r.analysis.issue_type==='None')throw Error('The local detector could not confirm this issue. Review the captured frame.');}if(!r.analysis.analysis_id)throw Error('Shared incident storage needs a trusted local-analysis bridge. Use the local prototype workspace for now.');const image_url=r.analysis.image_url;const {data,error}=await client.rpc('submit_incident',{p_analysis_id:r.analysis.analysis_id,p_lat:r.latitude,p_lng:r.longitude,p_address:r.address,p_importance:r.importance||'residential',p_image:image_url,p_duplicate:duplicate?.id||null});if(error)throw Error(error.message);id=data;if(r.scan_context){const {error:contextError}=await client.rpc('record_scan_context',{p_id:id,p_context:r.scan_context});if(contextError)toast('Incident saved; scan metadata needs the scan-context database update.')}await refresh();}else if(duplicate){if(duplicate.mine)throw Error('You already reported this incident in this session.');duplicate.reports++;duplicate.mine=true;duplicate.history.push({status:'Citizen confirmed same issue',created_at:now()});id=duplicate.id;}else{const i={...r,...r.analysis,id:'CIV-'+crypto.randomUUID().slice(0,8).toUpperCase(),reports:1,status:r.analysis.requires_review||r.analysis.confidence===null||r.analysis.confidence<.7?'Review Required':'Pending',department:departments[r.analysis.issue_type],created_at:now(),updated_at:now(),image_url:r.image,mine:true,history:[{status:'Reported',created_at:now()}]};incidents.unshift(i);id=i.id;}state.report=null;toast(duplicate?'Added your report to the existing incident.':'Incident submitted and routed to the department.');openIncident(id);}
async function action(kind,value=null){const i=state.selected;if(!i)throw Error('Select an incident first.');if(state.live){const {error}=await client.rpc('incident_action',{p_id:i.id,p_action:kind,p_value:value});if(error)throw Error(error.message);await refresh();}else{if(kind==='assign'){if(!value)throw Error('Select a worker.');i.worker_id=value;i.status='Assigned';i.assigned_at=now()}else if(kind==='department'){i.department=value}else if(kind==='review'){i.status='Review Required'}else if(kind==='reject'){i.status='Rejected'}else if(kind==='approve'){if(!i.after_image_url)throw Error('An after-repair image is required.');i.status='Resolved';i.verification_explanation='Authority approved after visual review.'}else if(kind==='support'){if(i.mine)throw Error('You already reported this issue.');i.reports++;i.mine=true}else if(kind==='status'){i.status=value}i.updated_at=now();i.history.push({status:kind==='department'?'Department changed to '+value:kind==='support'?'Citizen confirmed same issue':i.status,created_at:now()});}render();toast('Incident updated');}
function completion(){afterPhoto=null;verificationResult=null;modal(`<h2>Verify the repair</h2><p>Upload an after-repair photo showing the same location and a similar angle.</p><div class="photo-pair"><div><h4>BEFORE</h4>${photo(state.selected.image_url)}</div><div><h4>AFTER</h4><div id="after-preview" class="photo-placeholder">New image required</div></div></div><label class="field">After-repair image<input type="file" id="after-file" accept="image/jpeg,image/png,image/webp" required></label>${state.live||state.selected.demo===false?'':`<label class="field">Simulated verification result<select id="demo-verify"><option value="None">Issue no longer visible (pass)</option><option value="${state.selected.issue_type}">Issue still visible (fail)</option></select></label><p class="subtext">This rehearses the review workflow. It is not AI verification.</p>`}<div id="verification-result" aria-live="polite"></div><div class="actions"><button class="btn" data-close>Cancel</button><button class="btn navy" id="verify" disabled>${icon('eye')}Verify image</button><button class="btn primary" id="finish" disabled>Submit completion</button></div>`);$('#after-file').onchange=()=>safe(async()=>{afterPhoto=await readImage($('#after-file').files[0]);$('#after-preview').outerHTML=`<div id="after-preview">${photo(afterPhoto)}</div>`;verificationResult=null;$('#verify').disabled=false;$('#finish').disabled=true;$('#verification-result').innerHTML=''});$('#verify').onclick=()=>safe(async()=>{if(afterPhoto===state.selected.image_url)throw Error('Upload a different, new after-repair image.');$('#verify').disabled=true;verificationResult=await analyze(afterPhoto,$('#demo-verify')?.value,'LOW',state.selected.image_url,state.selected.id);const passed=verificationResult.verified===true&&verificationResult.confidence>=.7;$('#verification-result').innerHTML=`<div class="${passed?'result':'notice'}"><h3>${state.selected.user_assisted?'Human evidence review':state.live||state.selected.demo===false?'AI evidence review':'Simulated verification'} ${passed?'passed':'needs review'}</h3><p>${esc(verificationResult.explanation)}</p><p class="subtext">Assessment: ${esc(confidenceText(verificationResult))} · ${passed?'Evidence suggests repair; review is still advised.':'Issue may remain or evidence may be insufficient. Authority review required.'}</p></div>`;$('#finish').disabled=false;$('#verify').disabled=false;});$('#finish').onclick=()=>safe(async()=>{if(!afterPhoto||!verificationResult)throw Error('Upload and verify the after image first.');$('#finish').disabled=true;const i=state.selected;if(state.live){const after_image_url=verificationResult.image_url;const {error}=await client.rpc('complete_incident',{p_id:i.id,p_analysis_id:verificationResult.analysis_id,p_after:after_image_url});if(error)throw Error(error.message);await refresh();}else{i.after_image_url=afterPhoto;i.verification_explanation=verificationResult.explanation;i.status=verificationResult.verified&&verificationResult.confidence>=.7?'Resolved':'Review Required';i.updated_at=now();i.history.push({status:i.status,created_at:now()});}$('#modal').close();render();toast('Completion evidence saved');});}
async function safe(fn){try{await fn()}catch(e){toast(e.message||'The action could not be completed.');document.querySelectorAll('#analyze,#submit-incident,#verify,#finish,#scan-start').forEach(b=>b.disabled=false)}}
function bindSecondary(){const click=(id,fn)=>{if($('#'+id))$('#'+id).onclick=()=>safe(fn)};click('new-report',()=>{state.report={};navigate('report')});click('citizen-camera',async()=>{state.report={};navigate('report');await camera()});click('open-camera',camera);click('stop-camera',closeCamera);click('capture',()=>{const image=captureFrame();rememberReport().image=image;state.report.analysis=null;closeCamera();render()});for(const id of ['upload-button','replace-photo'])click(id,()=>$('#image-file').click());if($('#image-file'))$('#image-file').onchange=()=>safe(async()=>{rememberReport().image=await readImage($('#image-file').files[0]);state.report.analysis=null;render()});click('analyze',async()=>{const r=rememberReport();$('#analyze').disabled=true;r.analysis=await analyze(r.image,$('#demo-type')?.value,$('#demo-severity')?.value);render()});click('submit-incident',async()=>{$('#submit-incident').disabled=true;await submitReport()});click('locate',async()=>{const r=rememberReport(),p=await geolocate();r.latitude=p.latitude;r.longitude=p.longitude;render();toast('Location captured. Add an address or area.')});click('nearby-location',async()=>{state.position=await geolocate();maps[0]?.setView([state.position.latitude,state.position.longitude],15);toast('Map centered on your current location')});for(const [id,kind,get]of[['assign-worker','assign',()=>$('#worker-select').value],['change-department','department',()=>$('#department-select').value],['review-incident','review',()=>null],['support-incident','support',()=>null],['worker-next','status',()=>$('#worker-next').dataset.status],['authority-resolve','approve',()=>null]])click(id,()=>action(kind,get()));click('reject-incident',()=>{modal('<h2>Reject this detection?</h2><p>The report will be retained in the history and removed from the active queue.</p><div class="actions"><button class="btn" data-close>Cancel</button><button class="btn danger" id="confirm-reject">Reject detection</button></div>');$('#confirm-reject').onclick=()=>safe(async()=>{$('#modal').close();await action('reject')})});click('completion',completion);if($('#login-form'))$('#login-form').onsubmit=e=>{e.preventDefault();safe(async()=>{const f=new FormData(e.target),{data,error}=await client.auth.signInWithPassword({email:f.get('email'),password:f.get('password')});if(error)throw Error(error.message);await enterLive(data.user);})};click('signup',()=>{modal(`<h2>Create a citizen account</h2><form id="signup-form"><label class="field">Name<input name="name" required autocomplete="name"></label><label class="field">Email<input type="email" name="email" required autocomplete="email"></label><label class="field">Password<input name="password" type="password" minlength="8" required autocomplete="new-password"></label><div class="actions"><button type="button" class="btn" data-close>Cancel</button><button class="btn primary">Create account</button></div></form>`);$('#signup-form').onsubmit=e=>{e.preventDefault();safe(async()=>{const f=new FormData(e.target),{error}=await client.auth.signUp({email:f.get('email'),password:f.get('password'),options:{data:{name:f.get('name')}}});if(error)throw Error(error.message);$('#modal').close();toast('Account created. Check your email, then sign in.')})}});if($('#settings-form'))$('#settings-form').onsubmit=e=>{e.preventDefault();safe(async()=>{const f=new FormData(e.target),url=new URL(f.get('url')),key=String(f.get('key')).trim();if(url.protocol!=='https:'||!url.hostname.endsWith('.supabase.co'))throw Error('Use your HTTPS Supabase project URL.');if(key.startsWith('sb_secret_'))throw Error('Use a public publishable key, not a secret key.');if(key.startsWith('eyJ')){try{if(JSON.parse(atob(key.split('.')[1])).role==='service_role')throw Error('Service-role keys must never be used in the browser.')}catch(err){if(err.message.includes('Service-role'))throw err;}}localStorage.setItem('civiceye-public-settings',JSON.stringify({supabaseUrl:url.origin,supabaseAnonKey:key}));location.hash='login';location.reload()})};click('disconnect',()=>{localStorage.removeItem('civiceye-public-settings');location.hash='home';location.reload()});click('scan-start',async()=>{await camera();$('#scan-status').textContent=state.live?'Scanning road…':'Demo camera preview';if(state.live)scanTimer=setInterval(()=>safe(scanFrame),12000)});click('scan-stop',()=>{closeCamera();clearInterval(scanTimer);$('#scan-status').textContent='Stopped'});click('video-upload',()=>$('#video-file').click());if($('#video-file'))$('#video-file').onchange=()=>safe(async()=>{const file=$('#video-file').files[0];if(!file?.type.startsWith('video/'))throw Error('Choose a video file.');closeCamera();const v=$('#camera');v.src=URL.createObjectURL(file);v.style.display='block';await v.play();$('#scan-status').textContent='Uploaded video';});click('scan-frame',scanFrame);bindFrames();document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>answer(b.dataset.question));if($('#ask-form'))$('#ask-form').onsubmit=e=>{e.preventDefault();answer($('#question').value)};}
function geolocate(){return new Promise((resolve,reject)=>{if(!navigator.geolocation)return reject(Error('GPS is unavailable. Select the location on the map.'));navigator.geolocation.getCurrentPosition(p=>resolve({latitude:p.coords.latitude,longitude:p.coords.longitude}),()=>reject(Error('Location permission denied or unavailable. Select the location on the map.')),{enableHighAccuracy:true,timeout:12000})})}
let scanning=false;async function scanFrame(){if(scanning)return;scanning=true;try{const image=captureFrame(),analysis=await analyze(image,$('#scan-demo-type')?.value);scanFeed.unshift({image,analysis,time:now()});scanFeed=scanFeed.slice(0,30);$('#scan-feed').innerHTML=scanFeedHtml();bindFrames();}finally{scanning=false}}
function bindFrames(){document.querySelectorAll('[data-frame]').forEach(b=>b.onclick=()=>{const f=scanFeed[Number(b.dataset.frame)];state.report={image:f.image,analysis:f.analysis};navigate('report')})}
const originalMaps=initMaps;initMaps=function(){originalMaps();const el=$('#location-map');if(el&&window.L){const m=maps.find(x=>x.getContainer()===el),r=state.report||{},lat=r.latitude??12.9735,lng=r.longitude??77.642;let marker=L.marker([lat,lng]).addTo(m);m.setView([lat,lng],15);m.on('click',e=>{rememberReport();state.report.latitude=e.latlng.lat;state.report.longitude=e.latlng.lng;$('#lat').value=e.latlng.lat.toFixed(6);$('#lng').value=e.latlng.lng.toFixed(6);marker.setLatLng(e.latlng)})}if($('#detail-map')&&state.selected){const m=maps.find(x=>x.getContainer().id==='detail-map');m?.setView([state.selected.latitude,state.selected.longitude],16)}};
async function enterLive(user){const {data,error}=await client.from('profiles').select('*').eq('id',user.id).single();if(error)throw Error('Your profile is not available. Ask your administrator to apply the schema.');state.user=data;state.role=data.role;await refresh();if(data.role==='authority'){const {data:w}=await client.from('profiles').select('id,name').eq('role','worker');state.workers=w||[]}navigate({citizen:'citizen',authority:'dashboard',worker:'tasks'}[data.role]);clearInterval(pollTimer);pollTimer=setInterval(async()=>{await refresh();if(['dashboard','incidents','tasks','analytics','reports','completed'].includes(state.page))render()},20000)}
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'read_civic_incidents',title:'Read CivicEye incidents',description:'Read incidents accessible in the signed-in CivicEye workspace.',inputSchema:{type:'object',properties:{status:{type:'string'}},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!state.role)throw Error('Enter a workspace first.');if(input.status!==undefined&&typeof input.status!=='string')throw Error('status must be a string');return incidents.filter(i=>!input.status||i.status===input.status).map(i=>({id:i.id,type:i.issue_type,priority:priority(i).level,status:i.status,address:i.address,reports:i.reports}))}})).catch(()=>{});Promise.resolve(document.modelContext.registerTool({name:'start_civic_report',title:'Start a civic report',description:'Open the report form; does not submit an incident.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute(){if(!state.role||state.role!=='citizen')throw Error('Citizen workspace required.');state.report={};navigate('report');return{opened:true,submitted:false}}})).catch(()=>{})}catch{}}
if(client)client.auth.getSession().then(({data})=>{if(data.session)safe(()=>enterLive(data.session.user))});



